/// <summary>
/// Purchase order header lists for the app (PO of today), read from PurchTable in X++ so the
/// app does not query the PurchaseOrderHeadersV2 OData entity. Registered as
/// HSMobileOpsPurchListSvc.
/// </summary>
class HSMobileOpsPurchListService
{
}

Method.Source:
/// <summary>
/// Purchase orders whose delivery date is DeliveryDate, for WarehouseId when given, in
/// purchase order order, at most maxOrders() of them.
/// </summary>
public HSMobileOpsOrdersForDateResponse getOrdersForDate(HSMobileOpsOrdersForDateRequest _request)
{
    HSMobileOpsOrdersForDateResponse response = new HSMobileOpsOrdersForDateResponse();
    HSMobileOpsOrderSummaryRow       row;
    List                             orders = new List(Types::Class);
    PurchTable                       purchTable;
    PurchLine                        purchLine;
    InventTrans                      inventTrans;
    InventTransOrigin                inventTransOrigin;
    TransDate                        deliveryDate;
    str                              warehouseId;
    int                              rows;

    response.parmSuccess(false);
    response.parmOrders(orders);

    if (!_request || !_request.parmDataAreaId() || !CompanyInfo::findDataArea(_request.parmDataAreaId()).RecId)
    {
        response.parmErrorCode('INVALID_REQUEST');
        return response;
    }
    deliveryDate = str2Date(_request.parmDeliveryDate(), 321);
    if (!deliveryDate)
    {
        response.parmErrorCode('INVALID_DATE');
        return response;
    }
    warehouseId = _request.parmWarehouseId();

    changecompany (_request.parmDataAreaId())
    {
        while select PurchId, OrderAccount, PurchStatus, DeliveryDate, InventSiteId, InventLocationId
            from purchTable
            order by PurchId
            where purchTable.DeliveryDate == deliveryDate
               && (!warehouseId || purchTable.InventLocationId == warehouseId)
        {
            row = new HSMobileOpsOrderSummaryRow();
            row.parmPurchId(purchTable.PurchId);
            row.parmVendorAccount(purchTable.OrderAccount);
            row.parmStatus(enum2Symbol(enumNum(PurchStatus), purchTable.PurchStatus));
            // Still Ordered in InventTrans, as HSMobileOpsReceivingService.orderedQtyByLine
            // reads it. RemainPurchPhysical only falls at product receipt, and this app
            // registers - so BSP-PO-000161706, fully registered, was offered under "Due
            // today - tap to start" and then answered "nothing left to receive".
            select firstonly RecId from purchLine
                where purchLine.PurchId     == purchTable.PurchId
                   && purchLine.PurchStatus != PurchStatus::Canceled
                   && !purchLine.IsDeleted
                exists join inventTransOrigin
                    where inventTransOrigin.InventTransId == purchLine.InventTransId
                exists join inventTrans
                    where inventTrans.InventTransOrigin == inventTransOrigin.RecId
                       && inventTrans.StatusReceipt     == StatusReceipt::Ordered;
            row.parmHasOpenLines(purchLine.RecId != 0);
            row.parmSiteId(purchTable.InventSiteId);
            row.parmWarehouseId(purchTable.InventLocationId);
            row.parmDeliveryDate(date2Str(purchTable.DeliveryDate, 321, DateDay::Digits2,
                DateSeparator::Hyphen, DateMonth::Digits2, DateSeparator::Hyphen, DateYear::Digits4));
            orders.addEnd(row);

            rows++;
            if (rows >= HSMobileOpsPurchListService::maxOrders())
            {
                break;
            }
        }
    }

    response.parmOrders(orders);
    response.parmSuccess(true);
    return response;
}

/// <summary>
/// The store's open purchase orders (user, 12 Nov: the Purchase orders enquiry): Open order
/// status with a line still Ordered in InventTrans - the HasOpenLines test of getOrdersForDate -
/// for WarehouseId, soonest delivery first. DeliveryDate is not used.
/// </summary>
public HSMobileOpsOrdersForDateResponse getOpenOrders(HSMobileOpsOrdersForDateRequest _request)
{
    HSMobileOpsOrdersForDateResponse response = new HSMobileOpsOrdersForDateResponse();
    HSMobileOpsOrderSummaryRow       row;
    List                             orders = new List(Types::Class);
    PurchTable                       purchTable;
    PurchLine                        purchLine;
    InventTrans                      inventTrans;
    InventTransOrigin                inventTransOrigin;
    str                              warehouseId;
    int                              rows;

    response.parmSuccess(false);
    response.parmOrders(orders);

    if (!_request || !_request.parmDataAreaId() || !_request.parmWarehouseId()
     || !CompanyInfo::findDataArea(_request.parmDataAreaId()).RecId)
    {
        response.parmErrorCode('INVALID_REQUEST');
        return response;
    }
    warehouseId = _request.parmWarehouseId();

    changecompany (_request.parmDataAreaId())
    {
        while select PurchId, OrderAccount, PurchStatus, DeliveryDate, InventSiteId, InventLocationId
            from purchTable
            order by DeliveryDate, PurchId
            where purchTable.InventLocationId == warehouseId
               && purchTable.PurchStatus      == PurchStatus::Backorder
               && purchTable.PurchaseType     == PurchaseType::Purch
            exists join purchLine
                where purchLine.PurchId     == purchTable.PurchId
                   && purchLine.PurchStatus != PurchStatus::Canceled
                   && !purchLine.IsDeleted
            exists join inventTransOrigin
                where inventTransOrigin.InventTransId == purchLine.InventTransId
            exists join inventTrans
                where inventTrans.InventTransOrigin == inventTransOrigin.RecId
                   && inventTrans.StatusReceipt     == StatusReceipt::Ordered
        {
            row = new HSMobileOpsOrderSummaryRow();
            row.parmPurchId(purchTable.PurchId);
            row.parmVendorAccount(purchTable.OrderAccount);
            row.parmStatus(enum2Symbol(enumNum(PurchStatus), purchTable.PurchStatus));
            row.parmHasOpenLines(true);
            row.parmSiteId(purchTable.InventSiteId);
            row.parmWarehouseId(purchTable.InventLocationId);
            row.parmDeliveryDate(date2Str(purchTable.DeliveryDate, 321, DateDay::Digits2,
                DateSeparator::Hyphen, DateMonth::Digits2, DateSeparator::Hyphen, DateYear::Digits4));
            orders.addEnd(row);

            rows++;
            if (rows >= HSMobileOpsPurchListService::maxOpenOrders())
            {
                response.parmErrorCode('TRUNCATED');
                break;
            }
        }
    }

    response.parmOrders(orders);
    response.parmSuccess(true);
    return response;
}

/// <summary>The same cap the app's list used over OData.</summary>
private static int maxOrders()
{
    return 200;
}
